"""
Everyday Echoes - 主应用
现代编辑风格个人博客系统

配色方案：
- 柔和白: #FAFAFA
- 木炭灰: #2D3436
- 柔和金: #D4AF37
"""

import os
import re
import uuid
import markdown
from datetime import datetime
from functools import wraps
from flask import Flask, render_template, request, jsonify, redirect, url_for, session, flash
from flask_cors import CORS
from werkzeug.utils import secure_filename
from models import db, Article, Tag, Series, Comment, Footnote, Subscriber, Newsletter, Admin

# 应用配置
app = Flask(__name__)
app.config['SECRET_KEY'] = 'everyday-echoes-secret-key-2024'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///everyday_echoes.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
app.config['UPLOAD_FOLDER'] = 'static/uploads'
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024  # 16MB

CORS(app)
db.init_app(app)

# Markdown 扩展配置
md = markdown.Markdown(extensions=[
    'extra',
    'codehilite',
    'toc',
    'tables',
    'fenced_code',
    'footnotes',
    'attr_list',
    'md_in_html'
])

ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'webp', 'md', 'markdown'}


def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS


def slugify(text):
    """生成URL友好的slug"""
    text = re.sub(r'[^\w\s-]', '', text.lower())
    return re.sub(r'[-\s]+', '-', text).strip('-')


def calculate_reading_time(content):
    """计算预计阅读时间"""
    words = len(content.split())
    return max(1, words // 200)


def login_required(f):
    """登录验证装饰器"""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'admin_id' not in session:
            if request.is_json:
                return jsonify({'error': '请先登录'}), 401
            return redirect(url_for('admin_login'))
        return f(*args, **kwargs)
    return decorated_function


