# ==================== 文章 API ====================

@app.route('/api/articles', methods=['GET'])
def get_articles():
    """获取文章列表"""
    page = request.args.get('page', 1, type=int)
    per_page = request.args.get('per_page', 10, type=int)
    tag = request.args.get('tag')
    series = request.args.get('series')
    year = request.args.get('year', type=int)
    featured = request.args.get('featured', type=bool)

    query = Article.query.filter_by(is_published=True)

    if tag:
        query = query.filter(Article.tags.any(Tag.slug == tag))
    if series:
        query = query.filter(Article.series.any(Series.slug == series))
    if year:
        query = query.filter(db.extract('year', Article.published_at) == year)
    if featured:
        query = query.filter_by(is_featured=True)

    query = query.order_by(Article.published_at.desc())
    pagination = query.paginate(page=page, per_page=per_page, error_out=False)

    return jsonify({
        'articles': [a.to_dict() for a in pagination.items],
        'total': pagination.total,
        'pages': pagination.pages,
        'current_page': page
    })


@app.route('/api/articles/featured', methods=['GET'])
