@app.route('/api/articles/<slug>', methods=['GET'])
def get_article_by_slug(slug):
    """通过slug获取文章"""
    article = Article.query.filter_by(slug=slug).first_or_404()
    data = article.to_dict(include_content=True)
    # 转换Markdown为HTML
    data['content_html'] = md.convert(article.content)
    md.reset()
    data['footnotes'] = [f.to_dict() for f in article.footnotes]
    return jsonify(data)


@app.route('/api/articles', methods=['POST'])
@login_required
def create_article():
    """创建文章"""
    data = request.json

    slug = slugify(data['title'])
    # 确保slug唯一
    base_slug = slug
    counter = 1
    while Article.query.filter_by(slug=slug).first():
        slug = f"{base_slug}-{counter}"
        counter += 1

    article = Article(
        title=data['title'],
        slug=slug,
        content=data['content'],
        excerpt=data.get('excerpt', data['content'][:200] + '...'),
        cover_image=data.get('cover_image'),
        weight=data.get('weight', 0),
        is_featured=data.get('is_featured', False),
        is_published=data.get('is_published', False),
        reading_time=calculate_reading_time(data['content'])
    )

    if data.get('is_published'):
        article.published_at = datetime.utcnow()

    # 处理标签
    if 'tags' in data:
        for tag_id in data['tags']:
            tag = Tag.query.get(tag_id)
            if tag:
                article.tags.append(tag)

    # 处理系列
    if 'series' in data:
        for series_id in data['series']:
            s = Series.query.get(series_id)
            if s:
                article.series.append(s)

    db.session.add(article)
    db.session.commit()

    return jsonify(article.to_dict()), 201


@app.route('/api/articles/<int:id>', methods=['PUT'])
@login_required
def update_article(id):
    """更新文章"""
    article = Article.query.get_or_404(id)
    data = request.json

    article.title = data.get('title', article.title)
    article.content = data.get('content', article.content)
    article.excerpt = data.get('excerpt', article.excerpt)
    article.cover_image = data.get('cover_image', article.cover_image)
    article.weight = data.get('weight', article.weight)
    article.is_featured = data.get('is_featured', article.is_featured)
    article.reading_time = calculate_reading_time(article.content)

    # 处理发布状态
    was_published = article.is_published
    article.is_published = data.get('is_published', article.is_published)
    if not was_published and article.is_published:
        article.published_at = datetime.utcnow()

    # 更新标签
    if 'tags' in data:
        article.tags = []
        for tag_id in data['tags']:
            tag = Tag.query.get(tag_id)
            if tag:
                article.tags.append(tag)

    # 更新系列
    if 'series' in data:
        article.series = []
        for series_id in data['series']:
            s = Series.query.get(series_id)
            if s:
                article.series.append(s)

    db.session.commit()
    return jsonify(article.to_dict())


