# ==================== Markdown上传 API ====================

@app.route('/api/upload/markdown', methods=['POST'])
@login_required
def upload_markdown():
    """上传Markdown文件"""
    if 'file' not in request.files:
        return jsonify({'error': '没有文件'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': '没有选择文件'}), 400

    if file and allowed_file(file.filename):
        content = file.read().decode('utf-8')

        # 解析YAML前置信息（如果有）
        title = secure_filename(file.filename).rsplit('.', 1)[0]
        excerpt = ''

        if content.startswith('---'):
            parts = content.split('---', 2)
            if len(parts) >= 3:
                front_matter = parts[1]
                content = parts[2].strip()

                # 简单解析前置信息
                for line in front_matter.split('\n'):
                    if ':' in line:
                        key, value = line.split(':', 1)
                        key = key.strip().lower()
                        value = value.strip().strip('"\'')
                        if key == 'title':
                            title = value
                        elif key == 'excerpt' or key == 'description':
                            excerpt = value

        return jsonify({
            'title': title,
            'content': content,
            'excerpt': excerpt or content[:200] + '...'
        })

    return jsonify({'error': '不支持的文件格式'}), 400


@app.route('/api/upload/image', methods=['POST'])
@login_required
def upload_image():
    """上传图片"""
    if 'file' not in request.files:
        return jsonify({'error': '没有文件'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': '没有选择文件'}), 400

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        unique_filename = f"{uuid.uuid4().hex}_{filename}"

        # 确定保存路径
        upload_type = request.form.get('type', 'media')
        if upload_type == 'cover':
            save_path = os.path.join(app.config['UPLOAD_FOLDER'], 'covers', unique_filename)
        else:
            save_path = os.path.join(app.config['UPLOAD_FOLDER'], 'media', unique_filename)

        file.save(save_path)
        return jsonify({
            'url': '/' + save_path,
            'filename': unique_filename
        })

    return jsonify({'error': '不支持的文件格式'}), 400


