# ==================== 订阅 API ====================

@app.route('/api/subscribe', methods=['POST'])
def subscribe():
    """订阅"""
    data = request.json
    email = data.get('email')

    if not email:
        return jsonify({'error': '请输入邮箱'}), 400

    existing = Subscriber.query.filter_by(email=email).first()
    if existing:
        if existing.is_active:
            return jsonify({'error': '该邮箱已订阅'}), 400
        existing.is_active = True
        existing.subscribed_at = datetime.utcnow()
        db.session.commit()
        return jsonify({'message': '重新订阅成功'})

    subscriber = Subscriber(
        email=email,
        name=data.get('name'),
        verification_token=uuid.uuid4().hex
    )
    db.session.add(subscriber)
    db.session.commit()

    return jsonify({'message': '订阅成功'})


@app.route('/api/unsubscribe/<token>', methods=['GET'])
def unsubscribe(token):
    """取消订阅"""
    subscriber = Subscriber.query.filter_by(verification_token=token).first_or_404()
    subscriber.is_active = False
    subscriber.unsubscribed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({'message': '取消订阅成功'})


