@app.route('/api/archive/years', methods=['GET'])
def get_archive_years():
    """获取存档年份列表"""
    years = db.session.query(
        db.extract('year', Article.published_at).label('year'),
        db.func.count(Article.id).label('count')
    ).filter(Article.is_published == True)\
     .group_by(db.extract('year', Article.published_at))\
     .order_by(db.desc('year')).all()

    return jsonify([{'year': int(y.year), 'count': y.count} for y in years if y.year])


