{% block extra_js %}
<script>
document.addEventListener('DOMContentLoaded', function() {
    // 加载精选文章
    loadFeaturedArticles();
    // 加载标签和年份过滤器
    loadFilters();
    // 加载文章列表
    loadArticles();

    // 初始化滑块
    initSlider();

    // 过滤器事件
    document.getElementById('tagFilter').addEventListener('change', () => loadArticles(1));
    document.getElementById('yearFilter').addEventListener('change', () => loadArticles(1));

    // 加载更多
    document.getElementById('loadMoreBtn').addEventListener('click', loadMore);

    // 订阅表单
    document.getElementById('subscribeForm').addEventListener('submit', handleSubscribe);
});

let currentPage = 1;
let totalPages = 1;
let sliderIndex = 0;
let featuredArticles = [];

async function loadFeaturedArticles() {
    try {
        const response = await fetch('/api/articles/featured');
        featuredArticles = await response.json();
        renderFeaturedSlider();
    } catch (error) {
        console.error('加载精选文章失败:', error);
    }
}

function renderFeaturedSlider() {
    const track = document.getElementById('sliderTrack');
    const dots = document.getElementById('sliderDots');

    if (featuredArticles.length === 0) {
        track.innerHTML = '<div class="featured-empty">暂无精选文章</div>';
        return;
    }

    track.innerHTML = featuredArticles.map((article, index) => `
        <div class="featured-slide ${index === 0 ? 'active' : ''}">
            <div class="featured-card">
                <div class="featured-image" style="background-image: url('${article.cover_image || '/static/uploads/covers/default.jpg'}')">
                    <div class="featured-overlay"></div>
                </div>
                <div class="featured-content">
                    <div class="featured-meta">
                        ${article.tags.slice(0, 2).map(tag => `
                            <span class="featured-tag" style="--tag-color: ${tag.color}">${tag.name}</span>
                        `).join('')}
                        <span class="featured-date">${formatDate(article.published_at)}</span>
                    </div>
                    <h3 class="featured-title">${article.title}</h3>
                    <p class="featured-excerpt">${article.excerpt}</p>
                    <a href="/article/${article.slug}" class="featured-link">
                        阅读全文
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M5 12h14M12 5l7 7-7 7"/>
                        </svg>
                    </a>
                </div>
            </div>
        </div>
    `).join('');

    dots.innerHTML = featuredArticles.map((_, index) => `
        <button class="slider-dot ${index === 0 ? 'active' : ''}" data-index="${index}"></button>
    `).join('');

    // 点击圆点切换
    dots.querySelectorAll('.slider-dot').forEach(dot => {
        dot.addEventListener('click', () => {
            sliderIndex = parseInt(dot.dataset.index);
            updateSlider();
        });
    });
}

function initSlider() {
    document.getElementById('sliderPrev').addEventListener('click', () => {
        sliderIndex = (sliderIndex - 1 + featuredArticles.length) % featuredArticles.length;
        updateSlider();
    });

    document.getElementById('sliderNext').addEventListener('click', () => {
        sliderIndex = (sliderIndex + 1) % featuredArticles.length;
        updateSlider();
    });

    // 自动轮播
    setInterval(() => {
        sliderIndex = (sliderIndex + 1) % featuredArticles.length;
        updateSlider();
    }, 6000);
}

function updateSlider() {
    const slides = document.querySelectorAll('.featured-slide');
    const dots = document.querySelectorAll('.slider-dot');

    slides.forEach((slide, index) => {
        slide.classList.toggle('active', index === sliderIndex);
    });

    dots.forEach((dot, index) => {
        dot.classList.toggle('active', index === sliderIndex);
    });
}

async function loadFilters() {
    // 加载标签
    try {
        const response = await fetch('/api/tags');
        const tags = await response.json();
        const tagSelect = document.getElementById('tagFilter');
        tags.forEach(tag => {
            tagSelect.innerHTML += `<option value="${tag.slug}">${tag.name} (${tag.article_count})</option>`;
        });
    } catch (error) {
        console.error('加载标签失败:', error);
    }

    // 加载年份
    try {
        const response = await fetch('/api/archive/years');
        const years = await response.json();
        const yearSelect = document.getElementById('yearFilter');
        years.forEach(item => {
            yearSelect.innerHTML += `<option value="${item.year}">${item.year}年 (${item.count})</option>`;
        });
    } catch (error) {
        console.error('加载年份失败:', error);
    }
}

async function loadArticles(page = 1) {
    currentPage = page;
    const tag = document.getElementById('tagFilter').value;
    const year = document.getElementById('yearFilter').value;

    let url = `/api/articles?page=${page}&per_page=9`;
    if (tag) url += `&tag=${tag}`;
    if (year) url += `&year=${year}`;

    try {
        const response = await fetch(url);
        const data = await response.json();
        totalPages = data.pages;

        const grid = document.getElementById('articlesGrid');

        if (page === 1) {
            grid.innerHTML = '';
        }

        if (data.articles.length === 0 && page === 1) {
            grid.innerHTML = '<div class="articles-empty">暂无文章</div>';
            document.getElementById('loadMoreBtn').style.display = 'none';
            return;
        }

        data.articles.forEach(article => {
            grid.innerHTML += createArticleCard(article);
        });

        document.getElementById('loadMoreBtn').style.display = 
            currentPage >= totalPages ? 'none' : 'flex';

    } catch (error) {
        console.error('加载文章失败:', error);
    }
}

function createArticleCard(article) {
    return `
        <article class="article-card">
            <a href="/article/${article.slug}" class="article-card-link">
                <div class="article-card-image" style="background-image: url('${article.cover_image || '/static/uploads/covers/default.jpg'}')">
                    <div class="article-card-overlay"></div>
                </div>
                <div class="article-card-content">
                    <div class="article-card-meta">
                        ${article.tags.slice(0, 1).map(tag => `
                            <span class="article-card-tag" style="--tag-color: ${tag.color}">${tag.name}</span>
                        `).join('')}
                        <span class="article-card-reading">${article.reading_time} 分钟阅读</span>
                    </div>
                    <h3 class="article-card-title">${article.title}</h3>
                    <p class="article-card-excerpt">${article.excerpt}</p>
                    <div class="article-card-footer">
                        <span class="article-card-date">${formatDate(article.published_at)}</span>
                        <span class="article-card-views">${article.view_count} 次阅读</span>
                    </div>
                </div>
            </a>
        </article>
    `;
}

function loadMore() {
    if (currentPage < totalPages) {
        loadArticles(currentPage + 1);
    }
}

async function handleSubscribe(e) {
    e.preventDefault();
    const email = e.target.querySelector('input').value;

    try {
        const response = await fetch('/api/subscribe', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email })
        });

        const data = await response.json();

        if (response.ok) {
            showToast('订阅成功！感谢你的关注。', 'success');
            e.target.reset();
        } else {
            showToast(data.error || '订阅失败，请稍后再试', 'error');
        }
    } catch (error) {
        showToast('网络错误，请稍后再试', 'error');
    }
}

function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' });
}

function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.textContent = message;
    document.body.appendChild(toast);

    setTimeout(() => toast.classList.add('show'), 100);
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}
</script>
{% endblock %}

