{% block extra_js %}
<script>
const articleSlug = '{{ article.slug }}';
const articleId = {{ article.id }};

document.addEventListener('DOMContentLoaded', function() {
    loadArticleContent();
    loadComments();
    initReadingProgress();
    initCommentForm();
});

async function loadArticleContent() {
    try {
        const response = await fetch(`/api/articles/${articleSlug}`);
        const data = await response.json();

        // 渲染内容
        document.getElementById('articleContent').innerHTML = data.content_html;

        // 生成目录
        generateTOC();

        // 处理脚注
        if (data.footnotes && data.footnotes.length > 0) {
            renderFootnotes(data.footnotes);
        }

        // 处理图片画廊
        initGallery();

        // 代码高亮增强
        enhanceCodeBlocks();

    } catch (error) {
        console.error('加载文章内容失败:', error);
    }
}

function generateTOC() {
    const content = document.getElementById('articleContent');
    const headings = content.querySelectorAll('h2, h3');
    const tocNav = document.getElementById('tocNav');

    if (headings.length === 0) {
        document.getElementById('articleToc').style.display = 'none';
        return;
    }

    let tocHTML = '';
    headings.forEach((heading, index) => {
        const id = `heading-${index}`;
        heading.id = id;
        const level = heading.tagName === 'H2' ? 'toc-h2' : 'toc-h3';
        tocHTML += `<a href="#${id}" class="toc-link ${level}">${heading.textContent}</a>`;
    });

    tocNav.innerHTML = tocHTML;

    // 滚动高亮
    const observer = new IntersectionObserver(entries => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                document.querySelectorAll('.toc-link').forEach(link => link.classList.remove('active'));
                document.querySelector(`.toc-link[href="#${entry.target.id}"]`)?.classList.add('active');
            }
        });
    }, { rootMargin: '-20% 0px -80% 0px' });

    headings.forEach(heading => observer.observe(heading));
}

function renderFootnotes(footnotes) {
    const container = document.getElementById('articleFootnotes');
    const list = document.getElementById('footnotesList');

    container.style.display = 'block';
    list.innerHTML = footnotes.map(fn => `
        <li id="fn-${fn.marker}">
            ${fn.content}
            <a href="#fnref-${fn.marker}" class="footnote-back">↩</a>
        </li>
    `).join('');
}

function initGallery() {
    const images = document.querySelectorAll('.article-content img');

    images.forEach(img => {
        img.addEventListener('click', () => {
            const overlay = document.createElement('div');
            overlay.className = 'image-overlay';
            overlay.innerHTML = `
                <div class="image-overlay-content">
                    <img src="${img.src}" alt="${img.alt}">
                    <p class="image-caption">${img.alt || ''}</p>
                </div>
            `;
            overlay.addEventListener('click', () => overlay.remove());
            document.body.appendChild(overlay);
            setTimeout(() => overlay.classList.add('show'), 10);
        });
    });
}

function enhanceCodeBlocks() {
    document.querySelectorAll('pre code').forEach(block => {
        const wrapper = document.createElement('div');
        wrapper.className = 'code-block-wrapper';

        const copyBtn = document.createElement('button');
        copyBtn.className = 'code-copy-btn';
        copyBtn.innerHTML = `
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
            </svg>
        `;
        copyBtn.addEventListener('click', async () => {
            await navigator.clipboard.writeText(block.textContent);
            copyBtn.innerHTML = '✓';
            setTimeout(() => {
                copyBtn.innerHTML = `
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                        <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                    </svg>
                `;
            }, 2000);
        });

        block.parentNode.insertBefore(wrapper, block);
        wrapper.appendChild(block.parentNode.removeChild(block).parentNode);
        wrapper.appendChild(copyBtn);
    });
}

function initReadingProgress() {
    const progress = document.getElementById('readingProgress');
    const article = document.querySelector('.article-main');

    window.addEventListener('scroll', () => {
        const scrollTop = window.scrollY;
        const articleTop = article.offsetTop;
        const articleHeight = article.offsetHeight;
        const windowHeight = window.innerHeight;

        const progress_val = Math.min(100, Math.max(0, 
            ((scrollTop - articleTop + windowHeight * 0.5) / articleHeight) * 100
        ));

        progress.style.width = `${progress_val}%`;
    });
}

async function loadComments() {
    try {
        const response = await fetch(`/api/articles/${articleId}/comments`);
        const comments = await response.json();

        document.getElementById('commentsCount').textContent = `(${comments.length})`;

        const list = document.getElementById('commentsList');
        if (comments.length === 0) {
            list.innerHTML = '<p class="comments-empty">还没有评论，来发表第一条吧！</p>';
            return;
        }

        list.innerHTML = comments.map(comment => renderComment(comment)).join('');

    } catch (error) {
        console.error('加载评论失败:', error);
    }
}

function renderComment(comment, isReply = false) {
    const replyClass = isReply ? 'comment-reply' : '';
    return `
        <div class="comment ${replyClass}" id="comment-${comment.id}">
            <div class="comment-header">
                <div class="comment-avatar">${comment.author_name.charAt(0).toUpperCase()}</div>
                <div class="comment-meta">
                    <span class="comment-author">${escapeHtml(comment.author_name)}</span>
                    <span class="comment-date">${formatDate(comment.created_at)}</span>
                    ${comment.is_pinned ? '<span class="comment-pinned">置顶</span>' : ''}
                </div>
            </div>
            <div class="comment-body">${escapeHtml(comment.content)}</div>
            <div class="comment-actions">
                <button class="comment-action-btn" onclick="replyTo(${comment.id}, '${escapeHtml(comment.author_name)}')">
                    回复
                </button>
            </div>
            ${comment.replies && comment.replies.length > 0 ? `
                <div class="comment-replies">
                    ${comment.replies.map(reply => renderComment(reply, true)).join('')}
                </div>
            ` : ''}
        </div>
    `;
}

function initCommentForm() {
    document.getElementById('commentForm').addEventListener('submit', async (e) => {
        e.preventDefault();

        const formData = new FormData(e.target);
        const data = {
            author_name: formData.get('author_name'),
            author_email: formData.get('author_email'),
            content: formData.get('content'),
            parent_id: e.target.dataset.parentId || null
        };

        try {
            const response = await fetch(`/api/articles/${articleId}/comments`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });

            if (response.ok) {
                showToast('评论已提交，等待审核后显示', 'success');
                e.target.reset();
                delete e.target.dataset.parentId;
                document.getElementById('replyIndicator')?.remove();
            } else {
                const err = await response.json();
                showToast(err.error || '提交失败', 'error');
            }
        } catch (error) {
            showToast('网络错误', 'error');
        }
    });
}

function replyTo(commentId, authorName) {
    const form = document.getElementById('commentForm');
    form.dataset.parentId = commentId;

    document.getElementById('replyIndicator')?.remove();

    const indicator = document.createElement('div');
    indicator.id = 'replyIndicator';
    indicator.className = 'reply-indicator';
    indicator.innerHTML = `
        回复 <strong>${authorName}</strong>
        <button type="button" onclick="cancelReply()">取消</button>
    `;
    form.insertBefore(indicator, form.firstChild);

    form.querySelector('textarea').focus();
    form.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function cancelReply() {
    const form = document.getElementById('commentForm');
    delete form.dataset.parentId;
    document.getElementById('replyIndicator')?.remove();
}

function shareToWeibo() {
    const url = encodeURIComponent(window.location.href);
    const title = encodeURIComponent(document.title);
    window.open(`https://service.weibo.com/share/share.php?url=${url}&title=${title}`, '_blank');
}

function copyLink() {
    navigator.clipboard.writeText(window.location.href);
    showToast('链接已复制', 'success');
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' });
}

function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.textContent = message;
    document.body.appendChild(toast);

    setTimeout(() => toast.classList.add('show'), 100);
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}
</script>
{% endblock %}

