{% block extra_js %}
<script>
let currentFilterType = 'all';
let currentFilterValue = null;

document.addEventListener('DOMContentLoaded', function() {
    initFilterTabs();
    loadFilters();
    loadArchive();
    loadStats();

    // URL参数处理
    const params = new URLSearchParams(window.location.search);
    if (params.get('tag')) {
        applyFilter('tag', params.get('tag'));
    } else if (params.get('year')) {
        applyFilter('year', params.get('year'));
    } else if (params.get('series')) {
        applyFilter('series', params.get('series'));
    }
});

function initFilterTabs() {
    const tabs = document.querySelectorAll('.filter-tab');

    tabs.forEach(tab => {
        tab.addEventListener('click', () => {
            tabs.forEach(t => t.classList.remove('active'));
            tab.classList.add('active');

            // 显示对应面板
            document.querySelectorAll('.filter-panel').forEach(p => p.style.display = 'none');

            const filter = tab.dataset.filter;
            if (filter === 'year') {
                document.getElementById('yearPanel').style.display = 'block';
            } else if (filter === 'tag') {
                document.getElementById('tagPanel').style.display = 'block';
            } else if (filter === 'series') {
                document.getElementById('seriesPanel').style.display = 'block';
            } else {
                clearFilter();
            }
        });
    });

    document.getElementById('clearFilter').addEventListener('click', clearFilter);
}

async function loadFilters() {
    // 加载年份
    try {
        const response = await fetch('/api/archive/years');
        const years = await response.json();

        const yearGrid = document.getElementById('yearGrid');
        yearGrid.innerHTML = years.map(item => `
            <button class="year-btn" data-year="${item.year}">
                <span class="year-value">${item.year}</span>
                <span class="year-count">${item.count} 篇</span>
            </button>
        `).join('');

        yearGrid.querySelectorAll('.year-btn').forEach(btn => {
            btn.addEventListener('click', () => applyFilter('year', btn.dataset.year));
        });
    } catch (error) {
        console.error('加载年份失败:', error);
    }

    // 加载标签
    try {
        const response = await fetch('/api/tags');
        const tags = await response.json();

        const tagCloud = document.getElementById('tagCloud');
        tagCloud.innerHTML = tags.map(tag => `
            <button class="tag-btn" data-tag="${tag.slug}" style="--tag-color: ${tag.color}">
                ${tag.name}
                <span class="tag-count">${tag.article_count}</span>
            </button>
        `).join('');

        tagCloud.querySelectorAll('.tag-btn').forEach(btn => {
            btn.addEventListener('click', () => applyFilter('tag', btn.dataset.tag));
        });
    } catch (error) {
        console.error('加载标签失败:', error);
    }

    // 加载系列
    try {
        const response = await fetch('/api/series');
        const series = await response.json();

        const seriesGrid = document.getElementById('seriesGrid');
        if (series.length === 0) {
            seriesGrid.innerHTML = '<p class="no-series">暂无系列</p>';
            return;
        }

        seriesGrid.innerHTML = series.map(s => `
            <button class="series-btn" data-series="${s.slug}">
                <div class="series-info">
                    <span class="series-name">${s.name}</span>
                    <span class="series-count">${s.article_count} 篇文章</span>
                </div>
                ${s.is_complete ? '<span class="series-complete">已完结</span>' : ''}
            </button>
        `).join('');

        seriesGrid.querySelectorAll('.series-btn').forEach(btn => {
            btn.addEventListener('click', () => applyFilter('series', btn.dataset.series));
        });
    } catch (error) {
        console.error('加载系列失败:', error);
    }
}

function applyFilter(type, value) {
    currentFilterType = type;
    currentFilterValue = value;

    // 更新UI
    document.getElementById('currentFilter').style.display = 'flex';

    let label = '';
    if (type === 'year') label = `${value} 年`;
    else if (type === 'tag') label = `标签: ${value}`;
    else if (type === 'series') label = `系列: ${value}`;

    document.getElementById('filterValue').textContent = label;

    // 更新URL
    const url = new URL(window.location);
    url.searchParams.set(type, value);
    history.pushState({}, '', url);

    loadArchive();
}

function clearFilter() {
    currentFilterType = 'all';
    currentFilterValue = null;

    document.getElementById('currentFilter').style.display = 'none';

    // 清除URL参数
    history.pushState({}, '', window.location.pathname);

    // 重置tab
    document.querySelectorAll('.filter-tab').forEach(t => t.classList.remove('active'));
    document.querySelector('.filter-tab[data-filter="all"]').classList.add('active');
    document.querySelectorAll('.filter-panel').forEach(p => p.style.display = 'none');

    loadArchive();
}

async function loadArchive() {
    let url = '/api/articles?per_page=100';

    if (currentFilterType === 'tag' && currentFilterValue) {
        url += `&tag=${currentFilterValue}`;
    } else if (currentFilterType === 'year' && currentFilterValue) {
        url += `&year=${currentFilterValue}`;
    } else if (currentFilterType === 'series' && currentFilterValue) {
        url += `&series=${currentFilterValue}`;
    }

    try {
        const response = await fetch(url);
        const data = await response.json();

        const timeline = document.getElementById('archiveTimeline');
        const empty = document.getElementById('archiveEmpty');

        if (data.articles.length === 0) {
            timeline.style.display = 'none';
            empty.style.display = 'block';
            return;
        }

        timeline.style.display = 'block';
        empty.style.display = 'none';

        // 按年月分组
        const grouped = groupByYearMonth(data.articles);

        timeline.innerHTML = Object.entries(grouped).map(([yearMonth, articles]) => `
            <div class="timeline-group">
                <div class="timeline-header">
                    <span class="timeline-date">${yearMonth}</span>
                    <span class="timeline-count">${articles.length} 篇</span>
                </div>
                <div class="timeline-articles">
                    ${articles.map(article => `
                        <a href="/article/${article.slug}" class="timeline-article">
                            <div class="timeline-article-main">
                                <h3 class="timeline-article-title">${article.title}</h3>
                                <p class="timeline-article-excerpt">${article.excerpt}</p>
                            </div>
                            <div class="timeline-article-meta">
                                <span class="timeline-article-date">${formatDay(article.published_at)}</span>
                                <span class="timeline-article-reading">${article.reading_time} 分钟</span>
                            </div>
                        </a>
                    `).join('')}
                </div>
            </div>
        `).join('');

    } catch (error) {
        console.error('加载存档失败:', error);
    }
}

function groupByYearMonth(articles) {
    const groups = {};

    articles.forEach(article => {
        if (!article.published_at) return;
        const date = new Date(article.published_at);
        const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;

        if (!groups[key]) groups[key] = [];
        groups[key].push(article);
    });

    return groups;
}

async function loadStats() {
    try {
        const response = await fetch('/api/stats');
        const stats = await response.json();

        animateNumber('statArticles', stats.total_articles);
        animateNumber('statViews', stats.total_views);
        animateNumber('statComments', stats.total_comments);

    } catch (error) {
        console.error('加载统计失败:', error);
    }
}

function animateNumber(elementId, target) {
    const element = document.getElementById(elementId);
    const duration = 1000;
    const start = 0;
    const startTime = performance.now();

    function update(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);

        const eased = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(start + (target - start) * eased);

        element.textContent = current.toLocaleString();

        if (progress < 1) {
            requestAnimationFrame(update);
        }
    }

    requestAnimationFrame(update);
}

function formatDay(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return `${date.getMonth() + 1}月${date.getDate()}日`;
}
</script>
{% endblock %}

