{% block extra_js %}
<script src="https://cdn.jsdelivr.net/npm/marked/marked.min.js"></script>
<script>
let selectedTags = [];

document.addEventListener('DOMContentLoaded', function() {
    initTabs();
    initUpload();
    initEditor();
    loadTags();
    initCoverUpload();
});

function initTabs() {
    const tabs = document.querySelectorAll('.write-tab');
    const panels = document.querySelectorAll('.write-panel');

    tabs.forEach(tab => {
        tab.addEventListener('click', () => {
            tabs.forEach(t => t.classList.remove('active'));
            panels.forEach(p => p.classList.remove('active'));

            tab.classList.add('active');
            document.getElementById(`${tab.dataset.panel}Panel`).classList.add('active');
        });
    });
}

function initUpload() {
    const zone = document.getElementById('uploadZone');
    const input = document.getElementById('uploadInput');

    zone.addEventListener('click', () => input.click());

    zone.addEventListener('dragover', (e) => {
        e.preventDefault();
        zone.classList.add('dragover');
    });

    zone.addEventListener('dragleave', () => {
        zone.classList.remove('dragover');
    });

    zone.addEventListener('drop', (e) => {
        e.preventDefault();
        zone.classList.remove('dragover');

        const file = e.dataTransfer.files[0];
        if (file) handleFileUpload(file);
    });

    input.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) handleFileUpload(file);
    });

    document.getElementById('continueEdit').addEventListener('click', () => {
        document.querySelector('.write-tab[data-panel="editor"]').click();
    });

    document.getElementById('uploadAnother').addEventListener('click', () => {
        document.getElementById('parsedResult').style.display = 'none';
        document.getElementById('uploadZone').style.display = 'block';
        input.value = '';
    });
}

async function handleFileUpload(file) {
    const formData = new FormData();
    formData.append('file', file);

    try {
        const response = await fetch('/api/upload/markdown', {
            method: 'POST',
            body: formData
        });

        if (!response.ok) {
            const err = await response.json();
            showToast(err.error || '上传失败', 'error');
            return;
        }

        const data = await response.json();

        // 填充编辑器
        document.getElementById('articleTitle').value = data.title;
        document.getElementById('articleContent').value = data.content;
        document.getElementById('articleExcerpt').value = data.excerpt;

        // 更新预览
        updatePreview();

        // 显示解析结果
        document.getElementById('uploadZone').style.display = 'none';
        document.getElementById('parsedResult').style.display = 'block';
        document.getElementById('parsedTitle').textContent = data.title;
        document.getElementById('parsedExcerpt').textContent = data.excerpt;

        showToast('文件解析成功！', 'success');

    } catch (error) {
        showToast('上传失败: ' + error.message, 'error');
    }
}

function initEditor() {
    const content = document.getElementById('articleContent');

    content.addEventListener('input', debounce(updatePreview, 300));

    document.getElementById('articleForm').addEventListener('submit', handleSubmit);
}

function updatePreview() {
    const content = document.getElementById('articleContent').value;
    const preview = document.getElementById('previewContent');

    if (!content.trim()) {
        preview.innerHTML = '<p style="color: var(--charcoal-light);">开始输入内容查看预览...</p>';
        return;
    }

    preview.innerHTML = marked.parse(content);
}

async function loadTags() {
    try {
        const response = await fetch('/api/tags');
        const tags = await response.json();

        const selector = document.getElementById('tagSelector');
        selector.innerHTML = tags.map(tag => `
            <div class="tag-option" data-id="${tag.id}" style="--tag-color: ${tag.color}">
                ${tag.name}
            </div>
        `).join('');

        selector.querySelectorAll('.tag-option').forEach(opt => {
            opt.addEventListener('click', () => {
                opt.classList.toggle('selected');
                const id = parseInt(opt.dataset.id);

                if (opt.classList.contains('selected')) {
                    selectedTags.push(id);
                } else {
                    selectedTags = selectedTags.filter(t => t !== id);
                }
            });
        });

    } catch (error) {
        console.error('加载标签失败:', error);
    }
}

function initCoverUpload() {
    const btn = document.getElementById('coverBtn');
    const input = document.getElementById('coverInput');
    const preview = document.getElementById('coverPreview');

    btn.addEventListener('click', () => input.click());

    input.addEventListener('change', async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        const formData = new FormData();
        formData.append('file', file);
        formData.append('type', 'cover');

        try {
            const response = await fetch('/api/upload/image', {
                method: 'POST',
                body: formData
            });

            const data = await response.json();

            if (response.ok) {
                preview.innerHTML = `<img src="${data.url}" alt="封面预览">`;
                document.getElementById('coverUrl').value = data.url;
                showToast('封面上传成功', 'success');
            } else {
                showToast(data.error || '上传失败', 'error');
            }
        } catch (error) {
            showToast('上传失败', 'error');
        }
    });
}

async function handleSubmit(e) {
    e.preventDefault();

    const data = {
        title: document.getElementById('articleTitle').value,
        content: document.getElementById('articleContent').value,
        excerpt: document.getElementById('articleExcerpt').value || undefined,
        cover_image: document.getElementById('coverUrl').value || undefined,
        is_featured: document.getElementById('isFeatured').checked,
        is_published: document.getElementById('isPublished').checked,
        tags: selectedTags
    };

    try {
        const response = await fetch('/api/articles', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data)
        });

        const result = await response.json();

        if (response.ok) {
            showToast('文章保存成功！', 'success');

            if (data.is_published) {
                setTimeout(() => {
                    window.location.href = `/article/${result.slug}`;
                }, 1000);
            }
        } else {
            showToast(result.error || '保存失败', 'error');
        }
    } catch (error) {
        showToast('保存失败: ' + error.message, 'error');
    }
}

function debounce(func, wait) {
    let timeout;
    return function(...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(this, args), wait);
    };
}

function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.textContent = message;
    document.body.appendChild(toast);

    setTimeout(() => toast.classList.add('show'), 100);
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}
</script>
{% endblock %}

