<script>
document.addEventListener('DOMContentLoaded', function() {
    loadSubscriberCount();
    initSubscribeForm();
});

async function loadSubscriberCount() {
    try {
        const response = await fetch('/api/stats');
        const stats = await response.json();

        const element = document.getElementById('subscriberCount');
        animateNumber(element, stats.total_subscribers);
    } catch (error) {
        console.error('加载订阅数失败:', error);
    }
}

function animateNumber(element, target) {
    const duration = 1500;
    const start = 0;
    const startTime = performance.now();

    function update(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);

        const eased = 1 - Math.pow(1 - progress, 4);
        const current = Math.floor(start + (target - start) * eased);

        element.textContent = current;

        if (progress < 1) {
            requestAnimationFrame(update);
        }
    }

    requestAnimationFrame(update);
}

function initSubscribeForm() {
    document.getElementById('subscribeForm').addEventListener('submit', async (e) => {
        e.preventDefault();

        const formData = new FormData(e.target);
        const data = {
            email: formData.get('email'),
            name: formData.get('name') || undefined
        };

        const btn = e.target.querySelector('button');
        const originalText = btn.innerHTML;
        btn.innerHTML = '处理中...';
        btn.disabled = true;

        try {
            const response = await fetch('/api/subscribe', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });

            const result = await response.json();

            if (response.ok) {
                showToast('🎉 ' + result.message, 'success');
                e.target.reset();

                // 更新计数
                const countEl = document.getElementById('subscriberCount');
                const currentCount = parseInt(countEl.textContent);
                animateNumber(countEl, currentCount + 1);
            } else {
                showToast(result.error || '订阅失败', 'error');
            }
        } catch (error) {
            showToast('网络错误，请稍后再试', 'error');
        } finally {
            btn.innerHTML = originalText;
            btn.disabled = false;
        }
    });
}

function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.textContent = message;
    document.body.appendChild(toast);

    setTimeout(() => toast.classList.add('show'), 100);
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}
</script>
