    padding: var(--space-6);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--transition-base);
}

.lightbox.open {
    opacity: 1;
    pointer-events: auto;
}

.lightbox img {
    max-width: 100%;
    max-height: 90vh;
    object-fit: contain;
    border-radius: var(--radius);
}

