/* ========================================
   Everyday Echoes - Main JavaScript
   Shared utilities and core functionality
   ======================================== */

'use strict';

// ----------------------------------------
// Global Utilities
// ----------------------------------------

const EverydayEchoes = {
    // API Base URL
    apiBase: '/api',

    // Debounce function
    debounce(fn, delay = 300) {
        let timeoutId;
        return function(...args) {
            clearTimeout(timeoutId);
            timeoutId = setTimeout(() => fn.apply(this, args), delay);
        };
    },

    // Throttle function
    throttle(fn, limit = 100) {
        let inThrottle;
        return function(...args) {
            if (!inThrottle) {
                fn.apply(this, args);
                inThrottle = true;
                setTimeout(() => inThrottle = false, limit);
            }
        };
    },

    // Format date
    formatDate(dateStr, options = {}) {
        const date = new Date(dateStr);
        const defaults = { year: 'numeric', month: 'long', day: 'numeric' };
        return date.toLocaleDateString('zh-CN', { ...defaults, ...options });
    },

    // Format relative time
    formatRelativeTime(dateStr) {
        const date = new Date(dateStr);
        const now = new Date();
        const diff = now - date;
        const seconds = Math.floor(diff / 1000);
        const minutes = Math.floor(seconds / 60);
        const hours = Math.floor(minutes / 60);
        const days = Math.floor(hours / 24);

        if (days > 30) return this.formatDate(dateStr);
        if (days > 0) return `${days}天前`;
        if (hours > 0) return `${hours}小时前`;
        if (minutes > 0) return `${minutes}分钟前`;
        return '刚刚';
    },

    // Slugify text
    slugify(text) {
        return text
            .toLowerCase()
            .replace(/[^\w\u4e00-\u9fa5]+/g, '-')
            .replace(/^-+|-+$/g, '');
    },

    // Escape HTML
    escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    },

    // Generate unique ID
    generateId() {
        return 'id-' + Math.random().toString(36).substr(2, 9);
    },

    // Copy to clipboard
    async copyToClipboard(text) {
        try {
            await navigator.clipboard.writeText(text);
            return true;
        } catch (err) {
            // Fallback for older browsers
            const textarea = document.createElement('textarea');
            textarea.value = text;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.select();
            try {
                document.execCommand('copy');
                return true;
            } catch (e) {
                return false;
            } finally {
                document.body.removeChild(textarea);
            }
        }
    },

    // API Fetch wrapper
    async api(endpoint, options = {}) {
        const url = endpoint.startsWith('http') ? endpoint : this.apiBase + endpoint;
        const defaults = {
            headers: {
                'Content-Type': 'application/json',
            },
        };

        try {
            const response = await fetch(url, { ...defaults, ...options });
            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.error || 'API request failed');
            }

            return data;
        } catch (error) {
            console.error('API Error:', error);
            throw error;
        }
    },

    // Get URL parameters
    getUrlParams() {
        return Object.fromEntries(new URLSearchParams(window.location.search));
    },

    // Set URL parameters
    setUrlParams(params) {
        const url = new URL(window.location);
        Object.entries(params).forEach(([key, value]) => {
            if (value === null || value === undefined || value === '') {
                url.searchParams.delete(key);
            } else {
                url.searchParams.set(key, value);
            }
        });
        window.history.pushState({}, '', url);
    },

    // Smooth scroll to element
    scrollTo(selector, offset = 80) {
        const element = typeof selector === 'string' 
            ? document.querySelector(selector) 
            : selector;

        if (element) {
            const top = element.getBoundingClientRect().top + window.scrollY - offset;
            window.scrollTo({ top, behavior: 'smooth' });
        }
    },

    // Check if element is in viewport
    isInViewport(element, threshold = 0) {
        const rect = element.getBoundingClientRect();
        return (
            rect.top >= -threshold &&
            rect.left >= 0 &&
            rect.bottom <= (window.innerHeight + threshold) &&
            rect.right <= window.innerWidth
        );
    },

    // Get reading time
    getReadingTime(text, wordsPerMinute = 200) {
        const words = text.trim().split(/\s+/).length;
        return Math.ceil(words / wordsPerMinute);
    },

    // Truncate text
    truncate(text, maxLength, suffix = '...') {
        if (text.length <= maxLength) return text;
        return text.substr(0, maxLength - suffix.length).trim() + suffix;
    }
};

// ----------------------------------------
// Toast Notifications
// ----------------------------------------

const Toast = {
    container: null,

    init() {
        if (!this.container) {
            this.container = document.createElement('div');
            this.container.className = 'toast-container';
            document.body.appendChild(this.container);
        }
    },

    show(message, type = 'info', duration = 3000) {
        this.init();

        const toast = document.createElement('div');
        toast.className = `toast toast-${type}`;

        const icons = {
            success: '✓',
            error: '✕',
            warning: '⚠',
            info: 'ℹ'
        };

        toast.innerHTML = `
            <span class="toast-icon">${icons[type] || icons.info}</span>
            <span class="toast-message">${EverydayEchoes.escapeHtml(message)}</span>
        `;

        this.container.appendChild(toast);

        setTimeout(() => {
            toast.classList.add('hide');
            setTimeout(() => toast.remove(), 300);
        }, duration);

        return toast;
    },

    success(message, duration) {
        return this.show(message, 'success', duration);
    },

    error(message, duration) {
        return this.show(message, 'error', duration);
    },

    warning(message, duration) {
        return this.show(message, 'warning', duration);
    },

    info(message, duration) {
        return this.show(message, 'info', duration);
    }
};

// ----------------------------------------
// Modal
// ----------------------------------------

const Modal = {
    activeModal: null,

    open(contentOrSelector) {
        // Close any existing modal
        this.close();

        let overlay;

        if (typeof contentOrSelector === 'string' && contentOrSelector.startsWith('#')) {
            // Use existing modal element
            overlay = document.querySelector(contentOrSelector);
        } else {
            // Create modal dynamically
            overlay = document.createElement('div');
            overlay.className = 'modal-overlay';
            overlay.innerHTML = `
                <div class="modal">
                    ${contentOrSelector}
                </div>
            `;
            document.body.appendChild(overlay);
        }

        if (overlay) {
            this.activeModal = overlay;

            // Prevent body scroll
            document.body.style.overflow = 'hidden';

            // Show modal
            requestAnimationFrame(() => {
                overlay.classList.add('open');
            });

            // Close on overlay click
            overlay.addEventListener('click', (e) => {
                if (e.target === overlay) {
                    this.close();
                }
            });

            // Close on escape key
            document.addEventListener('keydown', this.handleEscape);
        }

        return overlay;
    },

    close() {
        if (this.activeModal) {
            this.activeModal.classList.remove('open');
            document.body.style.overflow = '';
            document.removeEventListener('keydown', this.handleEscape);

            // Remove if dynamically created
            if (!this.activeModal.id) {
                setTimeout(() => {
                    this.activeModal.remove();
                }, 300);
            }

            this.activeModal = null;
        }
    },

    handleEscape(e) {
        if (e.key === 'Escape') {
            Modal.close();
        }
    },

    confirm(message, onConfirm, onCancel) {
        const content = `
            <div class="modal-header">
                <h3 class="modal-title">确认</h3>
                <button class="modal-close" data-action="close">&times;</button>
            </div>
            <div class="modal-body">
                <p>${EverydayEchoes.escapeHtml(message)}</p>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" data-action="cancel">取消</button>
                <button class="btn btn-primary" data-action="confirm">确认</button>
            </div>
        `;

        const overlay = this.open(content);

        overlay.addEventListener('click', (e) => {
            const action = e.target.dataset.action;
            if (action === 'confirm') {
                this.close();
                onConfirm && onConfirm();
            } else if (action === 'cancel' || action === 'close') {
                this.close();
                onCancel && onCancel();
            }
        });
    }
};

// ----------------------------------------
// Lightbox
