const Lightbox = {
    element: null,

    init() {
        if (!this.element) {
            this.element = document.createElement('div');
            this.element.className = 'lightbox';
            this.element.innerHTML = `
                <button class="lightbox-close">&times;</button>
                <img src="" alt="">
            `;
            document.body.appendChild(this.element);

            // Close handlers
            this.element.addEventListener('click', (e) => {
                if (e.target === this.element || e.target.classList.contains('lightbox-close')) {
                    this.close();
                }
            });

            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && this.element.classList.contains('open')) {
                    this.close();
                }
            });
        }
    },

    open(src, alt = '') {
        this.init();
        const img = this.element.querySelector('img');
        img.src = src;
        img.alt = alt;
        this.element.classList.add('open');
        document.body.style.overflow = 'hidden';
    },

    close() {
        if (this.element) {
            this.element.classList.remove('open');
            document.body.style.overflow = '';
        }
    }
};

// ----------------------------------------
// Navigation
// ----------------------------------------

const Navigation = {
    init() {
        this.nav = document.querySelector('.nav');
        this.toggle = document.querySelector('.nav-toggle');
        this.links = document.querySelector('.nav-links');

        if (this.toggle && this.links) {
            this.toggle.addEventListener('click', () => this.toggleMenu());
        }

        // Scroll effect
        if (this.nav) {
            window.addEventListener('scroll', EverydayEchoes.throttle(() => {
                this.nav.classList.toggle('scrolled', window.scrollY > 20);
            }, 100));
        }

        // Active link
        this.setActiveLink();
    },

    toggleMenu() {
        this.toggle.classList.toggle('active');
        this.links.classList.toggle('open');
    },

    closeMenu() {
        this.toggle?.classList.remove('active');
        this.links?.classList.remove('open');
    },

    setActiveLink() {
        const path = window.location.pathname;
        const links = document.querySelectorAll('.nav-link');

        links.forEach(link => {
            const href = link.getAttribute('href');
            if (href === path || (href !== '/' && path.startsWith(href))) {
                link.classList.add('active');
            } else {
                link.classList.remove('active');
            }
        });
    }
};

// ----------------------------------------
// Reading Progress
// ----------------------------------------

const ReadingProgress = {
    init(contentSelector = '.article-content') {
        this.content = document.querySelector(contentSelector);
        this.bar = document.querySelector('.reading-progress-bar');

        if (this.content && this.bar) {
            window.addEventListener('scroll', EverydayEchoes.throttle(() => {
                this.update();
            }, 50));
        }
    },

    update() {
        const contentRect = this.content.getBoundingClientRect();
        const contentTop = contentRect.top + window.scrollY;
        const contentHeight = this.content.offsetHeight;
        const windowHeight = window.innerHeight;
        const scrollTop = window.scrollY;

        const start = contentTop - windowHeight;
        const end = contentTop + contentHeight;
        const current = scrollTop;

        let progress = ((current - start) / (end - start)) * 100;
        progress = Math.max(0, Math.min(100, progress));

        this.bar.style.width = `${progress}%`;
    }
};

// ----------------------------------------
// Table of Contents
// ----------------------------------------

const TableOfContents = {
    init(contentSelector = '.article-content', tocSelector = '.toc-list') {
        this.content = document.querySelector(contentSelector);
        this.toc = document.querySelector(tocSelector);

        if (this.content && this.toc) {
            this.generate();
            this.observeHeadings();
        }
    },

    generate() {
        const headings = this.content.querySelectorAll('h2, h3');

        if (headings.length === 0) {
            this.toc.parentElement.style.display = 'none';
            return;
        }

        let html = '';

        headings.forEach((heading, index) => {
            const id = heading.id || `heading-${index}`;
            heading.id = id;

            const level = heading.tagName.toLowerCase();
            const text = heading.textContent;

            html += `
                <a href="#${id}" class="toc-link toc-${level}" data-target="${id}">
                    ${EverydayEchoes.escapeHtml(text)}
                </a>
            `;
        });

        this.toc.innerHTML = html;

        // Click handling
        this.toc.addEventListener('click', (e) => {
            e.preventDefault();
            const link = e.target.closest('.toc-link');
            if (link) {
                const id = link.dataset.target;
                EverydayEchoes.scrollTo(`#${id}`);
            }
        });
    },

    observeHeadings() {
        const headings = this.content.querySelectorAll('h2, h3');

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const id = entry.target.id;
                    this.setActive(id);
                }
            });
        }, {
            rootMargin: '-100px 0px -70% 0px'
        });

        headings.forEach(heading => observer.observe(heading));
    },

    setActive(id) {
        const links = this.toc.querySelectorAll('.toc-link');
        links.forEach(link => {
            link.classList.toggle('active', link.dataset.target === id);
        });
    }
};

// ----------------------------------------
// Code Blocks
// ----------------------------------------

const CodeBlocks = {
    init() {
        const codeBlocks = document.querySelectorAll('pre code');

        codeBlocks.forEach(block => {
            const pre = block.parentElement;

            // Add copy button
            const copyBtn = document.createElement('button');
            copyBtn.className = 'code-copy-btn btn btn-sm btn-ghost';
            copyBtn.textContent = '复制';
            copyBtn.addEventListener('click', async () => {
                const success = await EverydayEchoes.copyToClipboard(block.textContent);
                copyBtn.textContent = success ? '已复制!' : '失败';
                setTimeout(() => copyBtn.textContent = '复制', 2000);
            });

            pre.style.position = 'relative';
            pre.appendChild(copyBtn);
        });
    }
};

// ----------------------------------------
// Forms
// ----------------------------------------

const Forms = {
    // Serialize form to object
    serialize(form) {
        const data = {};
        const formData = new FormData(form);

        for (const [key, value] of formData.entries()) {
            if (data[key]) {
                if (Array.isArray(data[key])) {
                    data[key].push(value);
                } else {
                    data[key] = [data[key], value];
                }
            } else {
                data[key] = value;
            }
        }

        return data;
    },

    // Validate form
    validate(form) {
        const inputs = form.querySelectorAll('[required]');
        let valid = true;

        inputs.forEach(input => {
            if (!input.value.trim()) {
                valid = false;
                this.showError(input, '此字段为必填项');
            } else if (input.type === 'email' && !this.isValidEmail(input.value)) {
                valid = false;
                this.showError(input, '请输入有效的邮箱地址');
            } else {
                this.clearError(input);
            }
        });

        return valid;
    },

    isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    },

    showError(input, message) {
        input.classList.add('is-invalid');

        let errorEl = input.nextElementSibling;
        if (!errorEl || !errorEl.classList.contains('form-error')) {
            errorEl = document.createElement('div');
            errorEl.className = 'form-error';
            input.parentNode.insertBefore(errorEl, input.nextSibling);
        }
        errorEl.textContent = message;
    },

    clearError(input) {
        input.classList.remove('is-invalid');
        const errorEl = input.nextElementSibling;
        if (errorEl && errorEl.classList.contains('form-error')) {
            errorEl.remove();
        }
    }
};

// ----------------------------------------
// Image Gallery
// ----------------------------------------

const ImageGallery = {
    init(selector = '.article-content img') {
        const images = document.querySelectorAll(selector);

        images.forEach(img => {
            img.style.cursor = 'pointer';
            img.addEventListener('click', () => {
                Lightbox.open(img.src, img.alt);
            });
        });
    }
};

// ----------------------------------------
// Lazy Loading
// ----------------------------------------

const LazyLoad = {
    init(selector = '[data-lazy]') {
        const images = document.querySelectorAll(selector);

        if ('IntersectionObserver' in window) {
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        const img = entry.target;
                        img.src = img.dataset.lazy;
                        img.removeAttribute('data-lazy');
                        observer.unobserve(img);
                    }
                });
            }, {
                rootMargin: '100px'
            });

            images.forEach(img => observer.observe(img));
        } else {
            // Fallback for older browsers
            images.forEach(img => {
                img.src = img.dataset.lazy;
            });
        }
    }
};

// ----------------------------------------
// Animate on Scroll
// ----------------------------------------

const AnimateOnScroll = {
    init(selector = '[data-animate]') {
        const elements = document.querySelectorAll(selector);

        if ('IntersectionObserver' in window) {
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('animated');
                        observer.unobserve(entry.target);
                    }
                });
            }, {
                threshold: 0.1
            });

            elements.forEach(el => observer.observe(el));
        } else {
            elements.forEach(el => el.classList.add('animated'));
        }
    }
};

// ----------------------------------------
// Share Functions
// ----------------------------------------

const Share = {
    weibo(title, url) {
        const shareUrl = `http://service.weibo.com/share/share.php?title=${encodeURIComponent(title)}&url=${encodeURIComponent(url)}`;
        window.open(shareUrl, '_blank', 'width=600,height=400');
    },

    async copyLink(url = window.location.href) {
        const success = await EverydayEchoes.copyToClipboard(url);
        if (success) {
            Toast.success('链接已复制到剪贴板');
        } else {
            Toast.error('复制失败，请手动复制');
        }
    },

    // Native share API if available
    async native(data) {
        if (navigator.share) {
            try {
                await navigator.share(data);
                return true;
            } catch (err) {
                if (err.name !== 'AbortError') {
                    console.error('Share failed:', err);
                }
            }
        }
        return false;
    }
};

// ----------------------------------------
// Counter Animation
// ----------------------------------------

const CounterAnimation = {
    animate(element, target, duration = 2000) {
        const start = 0;
        const startTime = performance.now();

        const update = (currentTime) => {
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);

            // Ease out cubic
            const eased = 1 - Math.pow(1 - progress, 3);
            const current = Math.floor(start + (target - start) * eased);

            element.textContent = current.toLocaleString();

            if (progress < 1) {
                requestAnimationFrame(update);
            }
        };

        requestAnimationFrame(update);
    },

    initAll(selector = '[data-counter]') {
        const counters = document.querySelectorAll(selector);

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const target = parseInt(entry.target.dataset.counter, 10);
                    this.animate(entry.target, target);
                    observer.unobserve(entry.target);
                }
            });
        }, { threshold: 0.5 });

        counters.forEach(counter => observer.observe(counter));
    }
};

// ----------------------------------------
// Storage Helper
// ----------------------------------------

const Storage = {
    get(key, defaultValue = null) {
        try {
            const value = localStorage.getItem(key);
            return value ? JSON.parse(value) : defaultValue;
        } catch {
            return defaultValue;
        }
    },

    set(key, value) {
        try {
            localStorage.setItem(key, JSON.stringify(value));
            return true;
        } catch {
            return false;
        }
    },

    remove(key) {
        try {
            localStorage.removeItem(key);
            return true;
        } catch {
            return false;
        }
    }
};

// ----------------------------------------
// Initialize on DOM Ready
// ----------------------------------------

document.addEventListener('DOMContentLoaded', () => {
    // Initialize navigation
    Navigation.init();

    // Initialize lazy loading
    LazyLoad.init();

    // Initialize scroll animations
    AnimateOnScroll.init();

    // Initialize counters
    CounterAnimation.initAll();

    // Close mobile menu on link click
    document.querySelectorAll('.nav-link').forEach(link => {
        link.addEventListener('click', () => Navigation.closeMenu());
    });
});

